#!/usr/bin/env python3
"""Render RESULTS.md from summary_*.json so no number is typed by hand."""
import json, sys, glob

files = sorted(glob.glob("summary_*.json"))
S = [json.load(open(f)) for f in files]


def pct(x): return f"{100*x:.1f}%"
def rng(c): return f"[{100*c[0]:.1f}, {100*c[1]:.1f}]"


L = ["# ARC-Challenge option-order robustness audit: results", "",
     "Generated by `make_report.py` from `summary_*.json`; every number below is computed by `analyze.py` from the raw per-prediction files. "
     "Intervals are 95% percentile bootstrap intervals over questions (5,000 resamples).", ""]
L += ["| | " + " | ".join(s["model"].split("/")[1] for s in S) + " |", "|---|" + "---|" * len(S)]
def row(name, f): L.append(f"| {name} | " + " | ".join(f(s) for s in S) + " |")
row("Questions (4-option, ARC-Challenge test)", lambda s: str(s["n_questions"]))
row("Predictions", lambda s: str(s["n_predictions"]))
row("Mean accuracy over 4 rotations", lambda s: f'{pct(s["metrics"]["acc_mean"])} {rng(s["ci95_bootstrap_over_questions"]["acc_mean"])}')
row("Accuracy by rotation 0/1/2/3", lambda s: " / ".join(pct(x) for x in s["acc_by_rotation"]))
row("Do rotations differ in accuracy? (Cochran's Q, df=3)", lambda s: f'Q={s["cochran_q_rotations"]["Q"]:.2f}, p={s["cochran_q_rotations"]["p"]:.2f}')
row("Correct under all 4 rotations", lambda s: f'{pct(s["metrics"]["acc_all_correct"])} {rng(s["ci95_bootstrap_over_questions"]["acc_all_correct"])}')
row("Correct under at least 1 rotation", lambda s: f'{pct(s["metrics"]["acc_any_correct"])}')
row("Answer flips (question's chosen answer changes with order)", lambda s: f'{pct(s["metrics"]["flip_rate"])} {rng(s["ci95_bootstrap_over_questions"]["flip_rate"])}')
row("Accuracy on flipping questions (chance = 25%)", lambda s: f'{pct(s["metrics"]["acc_on_flip"])} {rng(s["ci95_bootstrap_over_questions"]["acc_on_flip"])}')
row("Accuracy on stable questions", lambda s: f'{pct(s["metrics"]["acc_on_stable"])} {rng(s["ci95_bootstrap_over_questions"]["acc_on_stable"])}')
row("Flip rate expected from a pure position-bias predictor", lambda s: f'{pct(s["flip_rate_if_position_only_predictor"]["mean"])}')
row("Flip rate if rotation answers were shuffled across questions", lambda s: f'{pct(s["flip_rate_if_rotation_predictions_shuffled_across_questions"]["mean"])}')
row("Pick distribution over display slots A/B/C/D", lambda s: " / ".join(pct(s["display_position_pick_distribution"][str(i)]) for i in range(4)))
row("Accuracy when the correct answer sits in slot A/B/C/D", lambda s: " / ".join(pct(s["accuracy_by_correct_answer_display_position"][str(i)]) for i in range(4)))
row("Does correctness depend on the slot of the correct answer? (chi-square)", lambda s: f'chi2={s["slot_dependence_of_correctness_chi2"]["chi2"]:.1f}, df=3, p={s["slot_dependence_of_correctness_chi2"]["p"]:.1e}')
row("Expected calibration error (10 bins)", lambda s: f'{s["ece_10bin"]:.3f}')
row("Exact probability ties", lambda s: str(s["exact_ties"]))
print("\n".join(L))
open("RESULTS.md", "w").write("\n".join(L) + "\n")
